public class Main {
    // 将时间字符串转换为分钟数
    public static int parseTime(String time) {
        String[] parts = time.split(":");
        return Integer.parseInt(parts[0]) * 60 + Integer.parseInt(parts[1]);
    }
​
    // 计算费用（忽略免费时段 + 超过8小时不收费）
    public static int cost(int begin, int end) {
        if (end - begin < 30) return 0;
​
        int freeBegin = parseTime("11:30");
        int freeEnd = parseTime("13:30");
        int maxTime = 8 * 60;
​
        // 限制最大收费时长为8小时
        end = Math.min(end, begin + maxTime);
​
        int chargeTime = end - begin;
​
        // 跨越中午免费时间段的部分不收费
        if (begin <= freeEnd && end >= freeBegin) {
            chargeTime -= Math.min(end, freeEnd) - Math.max(begin, freeBegin);
        }
​
        // 每30分钟1元，向上取整
        return (chargeTime + 29) / 30;
    }
​
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.nextLine());
​
        // 读取包月车牌号
        Set<String> monthlyCars = new HashSet<>();
        String[] monthly = sc.nextLine().split(" ");
        if (n > 0) {
            monthlyCars.addAll(Arrays.asList(monthly));
        }
​
        // 存储非包月车的进出时间
        Map<String, int[]> carTimes = new HashMap<>();
​
        while (sc.hasNextLine()) {
            String line = sc.nextLine().trim();
            if (line.isEmpty()) continue;
​
            String[] parts = line.split(" ");
            String time = parts[0];
            String plate = parts[1];
            String status = parts[2];
​
            // 包月车跳过
            if (monthlyCars.contains(plate)) continue;
​
            int minutes = parseTime(time);
            carTimes.putIfAbsent(plate, new int[2]);
​
            if (status.equals("enter")) {
                carTimes.get(plate)[0] = minutes;
            } else {
                carTimes.get(plate)[1] = minutes;
            }
        }
​
        int total = 0;
        for (int[] times : carTimes.values()) {
            total += cost(times[0], times[1]);
        }
​
        System.out.println(total);
    }
}
