import (
    "bufio"
    "fmt"
    "os"
    "strconv"
    "strings"
)
​
// 将时间字符串转换为分钟数
func parseTime(t string) int {
    parts := strings.Split(t, ":")
    h, _ := strconv.Atoi(parts[0])
    m, _ := strconv.Atoi(parts[1])
    return h*60 + m
}
​
// 计算每辆车的花费
func cost(begin, end int) int {
    if end-begin < 30 {
        return 0
    }
​
    freeBegin := parseTime("11:30")
    freeEnd := parseTime("13:30")
    maxTime := 8 * 60
​
    // 限制最大收费时间
    if end > begin+maxTime {
        end = begin + maxTime
    }
​
    chargeTime := end - begin
​
    // 跨中午免费时间段的不计费
    if begin <= freeEnd && end >= freeBegin {
        overlap := min(end, freeEnd) - max(begin, freeBegin)
        chargeTime -= overlap
    }
​
    // 每30分钟1元，向上取整
    return (chargeTime + 29) / 30
}
​
func max(a, b int) int {
    if a > b {
        return a
    }
    return b
}
​
func min(a, b int) int {
    if a < b {
        return a
    }
    return b
}
​
func main() {
    scanner := bufio.NewScanner(os.Stdin)
    scanner.Scan()
    n, _ := strconv.Atoi(scanner.Text())
​
    monthly := make(map[string]bool)
    if n > 0 {
        scanner.Scan()
        plates := strings.Fields(scanner.Text())
        for _, plate := range plates {
            monthly[plate] = true
        }
    }
​
    carTimes := make(map[string][2]int)
​
    for scanner.Scan() {
        line := scanner.Text()
        if line == "" {
            continue
        }
​
        parts := strings.Fields(line)
        timeStr, plate, status := parts[0], parts[1], parts[2]
        // 忽略包月车
        if monthly[plate] {
            continue
        }
​
        t := parseTime(timeStr)
        record := carTimes[plate]
​
        if status == "enter" {
            record[0] = t
        } else {
            record[1] = t
        }
        carTimes[plate] = record
    }
​
    total := 0
    for _, times := range carTimes {
        total += cost(times[0], times[1])
    }
​
    fmt.Println(total)
}
